constraints:
1 ≤ N ≤ 10^{4}
0 ≤ A[i] ≤ 10^{6}

expected time complexity: O( N*log(N) )
expected auxiliary space: O(N)

standard_solution_code:
class Solution:

	def longestSubsequence(self, a, n):
		dp = [float('inf')] * (n + 1)
		dp[0] = float('-inf')
		max_len = 0
		for num in a:
			left = 0
			right = max_len
			while left <= right:
				mid = (left + right) // 2
				if dp[mid] < num:
					left = mid + 1
				else:
					right = mid - 1
			dp[left] = num
			max_len = max(max_len, left)
		return max_len
